  use z;
  constructor;
  . exact Rxz;
  . simp [Kripke.Satisfies, M];

private lemma subset_lem_frameTheorems_of_symmetric : Symmetric F → 𝗟𝗘𝗠 ⊆ F.theorems := by
  simp [Frame.theorems];
  rintro hSym φ _ V;
  apply Kripke.ValidOnModel.lem hSym;

